{
  "name": "lint-basis",
  "description": "The lint over the lead shop's definition corpus: checks the basis tree and the request, brief, and guidance records at the repository root against their typedefs' rules, derives an artifact type's definition chain from the references its documents carry, and checks one decision brief or one process definition alone. Use it before reporting any change to the tree, after editing a definition, brief, request, or guidance record, when a process definition names a tool, and when an artifact type's chain is wanted; it changes no file.",
  "uses": [
    {
      "name": "lint",
      "description": "Runs checks 1-13 over every markdown file under basis/ and over requests/, briefs/, guidance/, and initiatives/ at the repository root: frontmatter identity, unique `defines`, `$ref` sources, resolvable links, required headings, banned vocabulary, version and Document History, no numbered-decision reference, request frontmatter, brief frontmatter, tools named by process definitions, guidance frontmatter, and each parent initiative's Sub-initiatives list held to its children's `parent` fields. Reads only; writes and changes nothing. The tree is found from the tool's own location, so the current directory does not matter.",
      "invocation": "python3 basis/tools/lint_basis.py",
      "input_schema": {
        "type": "object",
        "properties": {},
        "additionalProperties": false
      },
      "returns": {
        "form": "text",
        "text": "the last line `PASS: 0 violation(s)` on standard output, nothing before it; exit status 0"
      },
      "failures": [
        {
          "code": "check-failed",
          "exit_status": 1,
          "condition": "the check found violations: one line per violation on standard output, `<path>[:<line>]: <what> (<clause>)`, then the last line `FAIL: <n> violation(s)`",
          "next": "repair each named file at the named clause, then run the same invocation again until its last line reads `PASS: 0 violation(s)`"
        },
        {
          "code": "usage",
          "exit_status": 2,
          "condition": "the arguments are not one of the four invocations this tool states; one line on standard error beginning `usage:` names them; nothing is checked",
          "next": "run the invocation the use states, as written"
        }
      ]
    },
    {
      "name": "check-brief",
      "description": "Checks one decision brief alone by check 10's rules: the decision-brief typedef's closed frontmatter field set, its status vocabulary, and that every `relates-to` path resolves from the repository root. Reads only; the rest of the tree is not checked.",
      "invocation": "python3 basis/tools/lint_basis.py --brief <path>",
      "input_schema": {
        "type": "object",
        "properties": {
          "path": {
            "type": "string",
            "description": "the path of the decision brief to check, relative to the current directory or absolute"
          }
        },
        "required": [
          "path"
        ],
        "additionalProperties": false
      },
      "returns": {
        "form": "text",
        "text": "the last line `PASS: 0 violation(s)` on standard output, nothing before it; exit status 0"
      },
      "failures": [
        {
          "code": "check-failed",
          "exit_status": 1,
          "condition": "the check found violations: one line per violation on standard output, `<path>[:<line>]: <what> (<clause>)`, then the last line `FAIL: <n> violation(s)`",
          "next": "repair each named file at the named clause, then run the same invocation again until its last line reads `PASS: 0 violation(s)`"
        },

