    "name": "write-cost-rows",
    "description": "Reads one run's anchor (a `bd` work item) and the harness's own usage report recorded on it, and writes the cost rows for that session's close beside the session record: one row per agent or human step and per top-level router turn, naming its step, role, wall-clock minutes, context tokens, output tokens, and tool uses \u2014 a field the usage report does not expose left blank, never estimated. No model computes a row. Use it from session-handoff-process's write-cost-rows step; an empty anchor writes nothing.",
    "uses": [
        {
            "name": "produce",
            "description": "Reads the anchor's comments and, for each step they record, the role and execution the named process definition gives that step; writes sessions/<session_id>-cost.md, creating the directory, overwriting what stands there. An empty or absent anchor writes nothing and prints nothing.",
            "invocation": "python3 basis/tools/write_cost_rows.py <session_id> --anchor <anchor_id>",
            "input_schema": {
                "type": "object",
                "properties": {
                    "session_id": {
                        "type": "string",
                        "description": "the session record's own id, e.g. sess-2026-09-08-a; the cost file pairs with sessions/<session_id>.md"
                    },
                    "anchor_id": {
                        "type": "string",
                        "description": "the bd work item id the run passed through the router on; empty (the default) means no anchor exists for this session",
                        "default": ""
                    }

